#!/usr/bin/env node
/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    —
 * depends    —
 * used by    —
 * ────────────────────────────────────────────────── generated by `pnpm map` ──
 */
/**
 * Build `thetowersdk.mcpb`, the MCP server as a one-click Claude Desktop extension.
 *
 * An MCP Bundle is a zip with a `manifest.json` at its root. Claude Desktop installs it, runs the
 * server with the Node runtime it ships, and asks the user for the settings the manifest declares.
 * Without one, using the server means installing the package somewhere and hand-editing a JSON
 * config to point at a path inside `node_modules`.
 *
 * What goes in is exactly what npm ships. The stage is `pnpm pack` unpacked, so it carries the
 * package's `files` and its exclusions, never a test or a source file the tarball leaves out. Its
 * runtime dependencies are installed from the committed lockfile, flat (`node-linker=hoisted`)
 * so the zip holds real files rather than pnpm's symlinks.
 *
 * The manifest is generated from `package.json`, so its version is the package's and cannot be
 * left behind on a release.
 *
 * Two settings, both mapped to environment variables the server already reads:
 *
 *   TOWER_TOOL_EXPORT        the game's `tool_export.json`. Optional: on a Mac the server finds it
 *                            in the game's container. Its default is the empty string, because
 *                            the bundle library leaves an unset optional `${user_config.…}` in
 *                            place as literal text, which the server would then try to open.
 *   TOWER_MECHANICS_MAP_DIR  where the map and ledger tools write. Set straight from `${HOME}`,
 *                            not through a setting: a setting's default is substituted after the
 *                            system directories, so `${HOME}` inside one would reach the server
 *                            unexpanded. Left unset, the server writes under its working
 *                            directory, which for an extension is not the user's to keep.
 *
 * The bundle CLI is fetched at an exact version rather than added to devDependencies, for the
 * reason `release.yml` gives for semantic-release: only this script uses it.
 *
 * Last, the packed file is unpacked into the OS temp directory and started there. The temp
 * directory has no `node_modules` above it, so a dependency the bundle forgot fails here instead
 * of being found in this checkout, the way it would be from a stage inside the repository.
 *
 * `dist/` must already be built: `pnpm build` first.
 *
 *     node scripts/build-mcpb.mjs    # writes .mcpb-build/thetowersdk.mcpb
 */
import { spawn, spawnSync } from 'node:child_process'
import { cpSync, existsSync, mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs'
import os from 'node:os'
import path from 'node:path'
import process from 'node:process'
import { fileURLToPath } from 'node:url'

/** Pinned. A packer that changes under you produces a bundle that changes under you. */
const MCPB_CLI = '@anthropic-ai/mcpb@2.1.2'

/** The newest manifest version `MCPB_CLI` validates. */
const MANIFEST_VERSION = '0.4'

/** Stable, so `releases/latest/download/thetowersdk.mcpb` always names the newest one. */
const BUNDLE_NAME = 'thetowersdk.mcpb'

const ROOT = path.join(path.dirname(fileURLToPath(import.meta.url)), '..')
const OUT_DIR = path.join(ROOT, '.mcpb-build')
const BUNDLE = path.join(OUT_DIR, BUNDLE_NAME)
const ICON = path.join(ROOT, 'site', 'static', 'TheTowerSDK_logo.png')

/** How long the started server gets to answer `tools/list`. */
const SMOKE_TIMEOUT_MS = 60_000

function run(command, args, options = {}) {
  const result = spawnSync(command, args, {
    stdio: 'inherit',
    shell: process.platform === 'win32',
    ...options,
  })
  if (result.status !== 0) {
    throw new Error(`${command} ${args.join(' ')} exited with ${result.status ?? result.signal}`)
  }
  return result
}

/** `Name (url)`, the form npm documents for a string `author`. */
function parseAuthor(author) {
  if (typeof author !== 'string') return author
  const match = author.match(/^\s*([^<(]+?)\s*(?:<([^>]+)>)?\s*(?:\(([^)]+)\))?\s*$/)
  if (!match) return { name: author }
  const [, name, email, url] = match
  return { name, ...(email ? { email } : {}), ...(url ? { url } : {}) }
}

function repositoryUrl(repository) {
  const url = typeof repository === 'string' ? repository : repository?.url
  return url?.replace(/^git\+/, '').replace(/\.git$/, '')
}

function buildManifest(pkg) {
  return {
    manifest_version: MANIFEST_VERSION,
    name: 'thetowersdk',
    display_name: 'The Tower SDK',
    version: pkg.version,
    description: pkg.description,
    long_description: [
      "Game data, formulas and save-file reading for The Tower, as tools an assistant can call: look up a table, run a calculator, decode the game's tool_export.json, read the community wiki, and plan an upgrade path from a real account.",
      '',
      "On a Mac the game's export is found automatically. Elsewhere, point the Tool Export setting at it.",
    ].join('\n'),
    author: parseAuthor(pkg.author),
    repository: { type: 'git', url: repositoryUrl(pkg.repository) },
    homepage: pkg.homepage,
    documentation: pkg.homepage,
    support: pkg.bugs?.url,
    icon: 'icon.png',
    server: {
      type: 'node',
      entry_point: 'mcp/server.mjs',
      mcp_config: {
        command: 'node',
        args: ['${__dirname}/mcp/server.mjs'],
        env: {
          TOWER_TOOL_EXPORT: '${user_config.tool_export}',
          TOWER_MECHANICS_MAP_DIR: '${HOME}/Documents/TheTowerSDK/mechanics-map',
        },
      },
    },
    // The server decides its tools at start-up, so the list is not written down here.
    tools_generated: true,
    keywords: pkg.keywords,
    license: pkg.license,
    compatibility: {
      platforms: ['darwin', 'win32', 'linux'],
      runtimes: { node: pkg.engines.node },
    },
    user_config: {
      tool_export: {
        type: 'file',
        title: 'Tool Export',
        description:
          "The game's tool_export.json. Leave empty on a Mac, where it is found in the game's own folder.",
        required: false,
        default: '',
      },
    },
  }
}

/** `pnpm pack`, unpacked: the stage holds what npm ships and nothing else. */
function stagePackage(workDir) {
  const tarballs = path.join(workDir, 'tarball')
  mkdirSync(tarballs, { recursive: true })
  run('pnpm', ['pack', '--pack-destination', tarballs], { cwd: ROOT, stdio: ['ignore', 'ignore', 'inherit'] })
  const [tarball] = readdirSync(tarballs).filter(name => name.endsWith('.tgz'))
  if (!tarball) throw new Error('pnpm pack wrote no tarball')
  run('tar', ['-xzf', path.join(tarballs, tarball), '-C', workDir])
  return path.join(workDir, 'package')
}

/** The runtime dependencies, from the committed lockfile, as real files. */
function installRuntimeDependencies(stage) {
  const lockfiles = ['pnpm-lock.yaml', 'pnpm-workspace.yaml']
  for (const name of lockfiles) cpSync(path.join(ROOT, name), path.join(stage, name))
  run(
    'pnpm',
    ['install', '--prod', '--frozen-lockfile', '--ignore-scripts', '--config.node-linker=hoisted'],
    { cwd: stage },
  )
  for (const name of lockfiles) rmSync(path.join(stage, name))
  // pnpm's own bookkeeping, which nothing at runtime reads.
  for (const name of readdirSync(path.join(stage, 'node_modules'))) {
    if (name.startsWith('.')) rmSync(path.join(stage, 'node_modules', name), { recursive: true, force: true })
  }
}

/** Start the server from the unpacked bundle and ask it for its tools. */
function smokeTest(unpacked, version) {
  const home = mkdtempSync(path.join(os.tmpdir(), 'thetowersdk-mcpb-home-'))
  const env = { ...process.env, TOWER_TOOL_EXPORT: '', TOWER_MECHANICS_MAP_DIR: path.join(home, 'mechanics-map') }
  delete env.TOWER_MONOREPO_ROOT
  const child = spawn(process.execPath, [path.join(unpacked, 'mcp', 'server.mjs')], {
    cwd: home,
    env,
    stdio: ['pipe', 'pipe', 'inherit'],
  })
  const send = message => child.stdin.write(`${JSON.stringify(message)}\n`)

  return new Promise((resolve, reject) => {
    let buffer = ''
    let serverVersion
    const timer = setTimeout(() => finish(new Error(`no tools/list answer within ${SMOKE_TIMEOUT_MS / 1000}s`)), SMOKE_TIMEOUT_MS)
    function finish(error, tools) {
      clearTimeout(timer)
      child.kill()
      rmSync(home, { recursive: true, force: true })
      if (error) reject(error)
      else resolve({ tools, serverVersion })
    }
    child.on('error', finish)
    child.on('exit', code => finish(new Error(`the server exited with ${code} before listing its tools`)))
    child.stdout.on('data', chunk => {
      buffer += chunk
      let newline
      while ((newline = buffer.indexOf('\n')) !== -1) {
        const line = buffer.slice(0, newline).trim()
        buffer = buffer.slice(newline + 1)
        if (!line) continue
        const message = JSON.parse(line)
        if (message.id === 1) {
          if (message.error) return finish(new Error(`initialize failed: ${JSON.stringify(message.error)}`))
          serverVersion = message.result?.serverInfo?.version
          send({ jsonrpc: '2.0', method: 'notifications/initialized' })
          send({ jsonrpc: '2.0', id: 2, method: 'tools/list' })
        }
        else if (message.id === 2) {
          const tools = message.result?.tools ?? []
          if (!tools.length) return finish(new Error(`tools/list returned no tools: ${line.slice(0, 400)}`))
          if (serverVersion && serverVersion !== version) {
            return finish(new Error(`the server reports version ${serverVersion}, the manifest ${version}`))
          }
          return finish(undefined, tools)
        }
      }
    })
    send({
      jsonrpc: '2.0',
      id: 1,
      method: 'initialize',
      params: { protocolVersion: '2025-06-18', capabilities: {}, clientInfo: { name: 'build-mcpb', version } },
    })
  })
}

if (!existsSync(path.join(ROOT, 'dist', 'index.js'))) {
  console.error('dist/ is missing: run `pnpm build` first.')
  process.exit(1)
}

const pkg = JSON.parse(readFileSync(path.join(ROOT, 'package.json'), 'utf8'))
const workDir = mkdtempSync(path.join(os.tmpdir(), 'thetowersdk-mcpb-'))
try {
  const stage = stagePackage(workDir)
  installRuntimeDependencies(stage)
  cpSync(ICON, path.join(stage, 'icon.png'))
  const manifestPath = path.join(stage, 'manifest.json')
  writeFileSync(manifestPath, `${JSON.stringify(buildManifest(pkg), null, 2)}\n`)

  run('pnpm', ['dlx', MCPB_CLI, 'validate', manifestPath])
  rmSync(OUT_DIR, { recursive: true, force: true })
  mkdirSync(OUT_DIR, { recursive: true })
  run('pnpm', ['dlx', MCPB_CLI, 'pack', stage, BUNDLE])

  const unpacked = path.join(workDir, 'unpacked')
  run('pnpm', ['dlx', MCPB_CLI, 'unpack', BUNDLE, unpacked])
  const { tools } = await smokeTest(unpacked, pkg.version)
  console.log(`\n${path.relative(ROOT, BUNDLE)}: version ${pkg.version}, ${tools.length} tools.`)
}
finally {
  rmSync(workDir, { recursive: true, force: true })
}
